package jp.tapmarker;
import java.util.*;
/** Independent heading and label masks for ordinary farm dialogs. */
final class FarmDialogEvidence {
 static final float[][] CLOSE={{.215f,.506f,.79f,.533f},{.40f,.648f,.60f,.676f}},START={{.215f,.759f,.435f,.784f},{.34f,.831f,.68f,.85f}};
 final Map<String,float[][]> refs=new HashMap<>();final Map<String,float[]> cached=new HashMap<>();final Map<String,Long> searched=new HashMap<>();int width,height;
 FarmDialogEvidence(Map<String,float[]> evidence){for(String key:new String[]{"close","start"}){ArrayList<float[]> list=new ArrayList<>();for(String name:new TreeSet<>(evidence.keySet()))if(name.startsWith("farm-control-"+key+"-")){float[] ref=evidence.get(name);if(ref.length!=1536)throw new IllegalArgumentException("農園のボタン見本");list.add(ref);}if(!list.isEmpty())refs.put(FarmPreset.P+key,list.toArray(new float[list.size()][]));}}
 static RegionSampler.Pixels mask(RegionSampler.Pixels pixels,boolean white){return(x,y)->{int c=pixels.get(x,y),r=c>>16&255,g=c>>8&255,b=c&255;boolean ink=white?Math.min(r,Math.min(g,b))>=222&&Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))<=35:Math.max(r,Math.max(g,b))<=95;return ink?0xffffffff:0xff000000;};}
 static float[] sample(int w,int h,String id,float[] t,RegionSampler.Pixels pixels){return AdaptiveLayout.paired(w,h,id.endsWith("close")?CLOSE:START,t,mask(pixels,id.endsWith("start")));}
 float score(String id,float[] data){float best=Float.POSITIVE_INFINITY;if(data!=null)for(float[] r:refs.get(id))best=Math.min(best,PhaseEngine.blockDistance(r,data));return best;}
 boolean locate(String id,int w,int h,RegionSampler.Pixels pixels,long now,Map<String,float[]> output){return locate(id,w,h,pixels,now,output,true);}
 boolean locate(String id,int w,int h,RegionSampler.Pixels pixels,long now,Map<String,float[]> output,boolean allowSearch){if(!refs.containsKey(id))return false;if(width!=w||height!=h){width=w;height=h;cached.clear();searched.clear();}float[] best=cached.getOrDefault(id,new float[]{1,1,0,0}).clone();float distance=score(id,sample(w,h,id,best,pixels)),limit=id.endsWith("start")?.016f:.008f;if(allowSearch&&distance>limit&&now-searched.getOrDefault(id,-1000L)>=1000){searched.put(id,now);for(float scale:new float[]{.90f,.94f,.98f,1,1.02f,1.06f})for(float dy:new float[]{-.04f,-.02f,0,.02f,.04f}){float[] t={1,scale,0,(1-scale)/2+dy};float d=score(id,sample(w,h,id,t,pixels));if(d<distance){distance=d;best=t;}}for(int pass=0;pass<4;pass++)for(int axis=0;axis<4;axis++)for(int sign:new int[]{-1,1}){float[] t=best.clone();t[axis]+=sign*(axis<2?.01f:.003f)/(1<<pass);if(t[0]<.85f||t[0]>1.12f||t[1]<.8f||t[1]>1.15f||Math.abs(t[2])>.08f||Math.abs(t[3])>.15f)continue;float d=score(id,sample(w,h,id,t,pixels));if(d<distance){distance=d;best=t;}}}if(distance>limit)return false;cached.put(id,best.clone());float[] b=AdaptiveLayout.map((id.endsWith("close")?CLOSE:START)[1],best);output.put(id,new float[]{1});output.put(id+AdaptiveLayout.BOUNDS,b);return true;}
}
